import { useServiceRequest } from '@pasarpolis/common-react-hooks'

import { useAuditLogContextValue } from '../../context'
import { AUDIT_LOG } from '../actions'

export const useAuditLogServiceCall = (actionsCall = () => {}) => {
  const [auditLogState, dispatch] = useAuditLogContextValue()
  const [callApi] = useServiceRequest(dispatch)
  const request = async (payload = {}) => {
    await callApi(actionsCall({
      ...payload
    }))
  }

  return [auditLogState, request]
}

export const useGetAuditLog = () => {
  return useAuditLogServiceCall(AUDIT_LOG.getAuditData)
}

export const useGetCategory = () => {
  return useAuditLogServiceCall(AUDIT_LOG.getCategories)
}

export const useGetUserList = () => {
  return useAuditLogServiceCall(AUDIT_LOG.getUserList)
}

export const useAddAuditReason = () => {
  return useAuditLogServiceCall(AUDIT_LOG.addAuditReason)
}

export const useResetState = () => {
  const [, dispatch] = useAuditLogContextValue()
  const resetState = (keys = []) => {
    dispatch(AUDIT_LOG.resetReduxStateAudit(keys))
  }
  return [resetState];
}




