/* eslint-disable react-hooks/exhaustive-deps */
import React, { useCallback, useEffect } from 'react'
import { Form, Input, Button } from 'antd'

import LayoutContent from '../../../../../components/utility/layoutContent'
import LayoutContentWrapper from '../../../../../components/utility/layoutWrapper'
import ReasonFormWrapper from "./style";
import { useAddAuditReason } from '../../state/hooks/useAuditLogContext'
import { useLoaderContextValue, useErrorContextValue, resetError  } from '@pasarpolis/common-react-hooks'


const FormItem = Form.Item
const { TextArea } = Input

const ReasonForm = ({form, history}) => {
  const [{addAuditReasonData = {}}, addAuditReason] = useAddAuditReason()
  const [{ ADD_AUDIT_REASON_LOADER }] = useLoaderContextValue();
  const [{addAuditReasonStatus = ''}, dispatchError] = useErrorContextValue()

  const validateForm = useCallback(async () => {
    return new Promise((resolve) => {
      form.validateFields((error, values) => {
        resolve(!error);
      });
    });
  }, [form]);

  const onSubmit = useCallback(
    async (e) => {
      e.preventDefault();
      const reason = form.getFieldValue("reason");
      const valid = await validateForm();
      if (!valid) {
        return;
      } else {
        addAuditReason({ body: { reason } });
      }
    },
    [form]
  );

  useEffect(() => {
    if(addAuditReasonStatus === 'success') {
      history.push({
        pathname: "/audit-log/list",
        search: `?reference_id=${addAuditReasonData?.reference_id}`,
      });
    }
    dispatchError(resetError({
      addAuditReasonStatus: ''
    }))
  }, [addAuditReasonStatus])

  const { getFieldDecorator } = form;
  return (
    <LayoutContentWrapper>
      <LayoutContent>
        <ReasonFormWrapper>
          <h2><b>Audit Log</b></h2>
          <Form className="reason-form" onSubmit={onSubmit}>
            <label className="custom-label">
              Before start, please fill in the reason of audit in the input box
              below.
            </label>
            <FormItem>
              {getFieldDecorator("reason", {
                rules: [{ required: true, message: "Reason can not be empty" }],
              })(
                <TextArea
                  rows={3}
                  size="small"
                  className="form-textarea"
                />
              )}
            </FormItem>
            <Button
              key="submit"
              type="primary"
              htmlType="submit"
              loading={!!ADD_AUDIT_REASON_LOADER}
              className="form-submit"
            >
              Submit
            </Button>
          </Form>
        </ReasonFormWrapper>
      </LayoutContent>
    </LayoutContentWrapper>
  );
}

export default Form.create({})(ReasonForm)
